#!/usr/bin/env python3
"""Ensure defusedxml is importable so the docx skill's unpack/pack helpers work."""
import importlib
import subprocess
import sys

try:
    importlib.import_module("defusedxml")
    print("defusedxml already available")
    sys.exit(0)
except ImportError:
    pass

for cmd in (
    [sys.executable, "-m", "pip", "install", "--quiet", "defusedxml"],
    [sys.executable, "-m", "pip", "install", "--user", "--quiet", "defusedxml"],
):
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if result.returncode == 0:
            break
    except Exception:
        continue
else:
    print("failed to install defusedxml", file=sys.stderr)
    sys.exit(1)

try:
    importlib.import_module("defusedxml")
    print("defusedxml installed successfully")
    sys.exit(0)
except ImportError as exc:
    print(f"defusedxml still not importable: {exc}", file=sys.stderr)
    sys.exit(1)

#!/usr/bin/env python3
"""Print raw XML of paragraphs identified as likely headlines."""
import sys
from pathlib import Path
import xml.dom.minidom as minidom

OUT = "unpacked"
HITS = {0: "EXECUTIVE SUMMARY", 5: "FINANCIAL HIGHLIGHTS", 14: "REVENUE BREAKDOWN BY SEGMENT",
        24: "KEY PERFORMANCE INDICATORS", 29: "OPERATING EXPENSES", 39: "Q1 2025 OUTLOOK",
        44: "RISK FACTORS"}

def main():
    dom = minidom.parse(str(Path(OUT) / "word" / "document.xml"))
    paras = dom.getElementsByTagName("w:p")
    for i, p in enumerate(paras):
        if i in HITS:
            print(f"=== paragraph {i}: {HITS[i]} ===")
            print(p.toxml())
            print()

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Underline all headline paragraphs in quarterly_report.docx (stdlib only).

Pipeline mirrors the docx skill's unpack -> edit -> pack workflow:
  1. parse unpacked/word/document.xml
  2. add <w:u w:val="single"/> to every run of each all-caps headline paragraph
  3. write edited document.xml back into the unpacked tree
  4. repack the tree into quarterly_report.docx
  5. verify by reopening the packed file
"""
import sys
import zipfile
from pathlib import Path
import xml.dom.minidom as minidom

SRC = "quarterly_report.docx"
UNPACKED = Path("unpacked")
DOCXML = UNPACKED / "word" / "document.xml"


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(p):
    text = para_text(p).strip()
    if not text:
        return False
    has_alpha = any(c.isalpha() for c in text)
    return has_alpha and text == text.upper()


def ensure_underline(run, dom):
    """Add <w:u w:val='single'/> to a run's rPr (creating rPr if needed)."""
    rprs = run.getElementsByTagName("w:rPr")
    if rprs:
        rpr = rprs[0]
        # dedupe: if an underline already exists, keep it
        for u in rpr.getElementsByTagName("w:u"):
            if u.getAttribute("w:val"):
                return
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        rpr.appendChild(u)
    else:
        rpr = dom.createElement("w:rPr")
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        rpr.appendChild(u)
        run.insertBefore(rpr, run.firstChild)


def main():
    if not DOCXML.exists():
        print("unpacked document.xml not found; run inspect_docx.py first", file=sys.stderr)
        return 1

    dom = minidom.parse(str(DOCXML))
    paras = dom.getElementsByTagName("w:p")
    changed = []
    for i, p in enumerate(paras):
        if is_headline(p):
            for run in p.getElementsByTagName("w:r"):
                ensure_underline(run, dom)
            changed.append((i, para_text(p).strip()))

    if not changed:
        print("ERROR: no headlines found", file=sys.stderr)
        return 1

    with open(DOCXML, "w", encoding="UTF-8") as fh:
        dom.writexml(fh, encoding="UTF-8", indent="", addindent="", newl="")
        fh.write("\n")

    print(f"underlined {len(changed)} headline paragraphs:")
    for i, text in changed:
        print(f"  [{i}] {text}")

    # Repack: zip the whole unpacked tree back into the original filename
    with zipfile.ZipFile(SRC, "w", zipfile.ZIP_DEFLATED) as zf:
        for f in sorted(UNPACKED.rglob("*")):
            if f.is_file():
                zf.write(f, f.relative_to(UNPACKED).as_posix())

    # Verification pass on the packed file
    with zipfile.ZipFile(SRC) as zf:
        data = zf.read("word/document.xml")
    vdom = minidom.parseString(data)
    vparas = vdom.getElementsByTagName("w:p")
    ok = True
    for i, p in enumerate(vparas):
        text = para_text(p).strip()
        if is_headline(p):
            runs = p.getElementsByTagName("w:r")
            if not runs:
                ok = False
                print(f"VERIFY FAIL: headline [{i}] {text!r} has no runs")
                continue
            for run in runs:
                rprs = run.getElementsByTagName("w:rPr")
                underlined = False
                if rprs:
                    for u in rprs[0].getElementsByTagName("w:u"):
                        if u.getAttribute("w:val") == "single":
                            underlined = True
                if not underlined:
                    ok = False
                    print(f"VERIFY FAIL: headline [{i}] {text!r} run not underlined")
            if ok:
                print(f"VERIFY OK: [{i}] {text!r} -> underlined")
        elif text and any(c.isalpha() for c in text):
            # confirm body text was not underlined
            for run in p.getElementsByTagName("w:r"):
                for rpr in run.getElementsByTagName("w:rPr"):
                    for u in rpr.getElementsByTagName("w:u"):
                        if u.getAttribute("w:val") == "single":
                            ok = False
                            print(f"VERIFY FAIL: non-headline [{i}] {text!r} got underline")

    if not ok:
        print("VERIFICATION FAILED", file=sys.stderr)
        return 1
    print("VERIFICATION PASSED: all headlines underlined, body untouched")
    return 0


if __name__ == "__main__":
    sys.exit(main())

